properties.schema-text:
{
  "type": "record",
  "name": "dim_product",
  "fields": [
    { "name": "id", "type": "int" },
    { "name": "variant_id", "type": "string" },
    { "name": "product_code", "type": "string" },
    { "name": "name", "type": "string" },

    { "name": "description", "type": ["string", "null"], "default": "Not Applicable" },

    {
      "name": "product_category_hierarchy",
      "type": {
        "type": "array",
        "items": "string"
      }
    },

    { "name": "product_category", "type": "string", "default": "Not Applicable" },
    { "name": "product_type", "type": "string", "default": "Not Applicable" },

    {
      "name": "unit_price",
      "type": {
        "type": "bytes",
        "logicalType": "decimal",
        "precision": 10,
        "scale": 2
      }
    },
    {
      "name": "unit_cost",
      "type": {
        "type": "bytes",
        "logicalType": "decimal",
        "precision": 10,
        "scale": 2
      }
    },

    { "name": "product_brand", "type": "string", "default": "Not Applicable" },

    { "name": "item_type", "type": ["string", "null"], "default": "Not Applicable" },
    { "name": "product_classification_status", "type": ["string", "null"], "default": "Not Applicable" },
    { "name": "product_classification_1", "type": ["string", "null"], "default": "Not Applicable" },
    { "name": "product_classification_grade", "type": ["string", "null"], "default": "Not Applicable" },
    { "name": "successor_model_product", "type": ["string", "null"], "default": "Not Applicable" },
    { "name": "is_combo_item", "type": ["string", "null"], "default": "Not Applicable" },

    { "name": "is_current", "type": ["int", "null"], "default": 1 },
    { "name": "source_system_code", "type": "int" }
  ]
}
